data.minimal_example:
final controller = MapController(
  location: const LatLng(Angle.degree(0), Angle.degree(0)),
  zoom: 2,
);

MapLayout(
  controller: controller,
  builder: (context, transformer) {
    return TileLayer(
      builder: (context, x, y, z) {
        return const SizedBox();
      },
    );
  },
);
